import { chromium } from 'playwright';
const b=await chromium.launch();const p=await b.newPage();
await p.goto('http://127.0.0.1:65166');
await p.fill('input[type=email],input[name=email]','ops@lab.test');
await p.fill('input[type=password]','lab-ops-pass');
await p.keyboard.press('Enter');
await p.waitForTimeout(1500);
await p.goto('http://127.0.0.1:65166/pipeline');
const want=['Invoicing','Picking','Quality check','Credit check','Intake','Packing','Shipping'];
for(let i=0;i<want.length;i++){
 const names=await p.locator('#pl .nm').allInnerTexts();
 if(names[i]===want[i])continue;
 const src=p.locator('#pl li').nth(names.indexOf(want[i])).locator('.h');
 const tb=await p.locator('#pl li').nth(i).boundingBox();
 const sb=await src.boundingBox();
 await p.mouse.move(sb.x+sb.width/2,sb.y+sb.height/2);await p.mouse.down();
 await p.mouse.move(sb.x+5,tb.y+2,{steps:8});await p.mouse.up();
}
console.log(await p.locator('#pl .nm').allInnerTexts());
await p.click('#save');await p.waitForTimeout(800);
console.log(await p.locator('#done').innerText());
await b.close();
